contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint depositAmount) public payable {
        require(depositAmount > 0);
        require(address(this).balance >= depositAmount);
        c.Deposit{value: depositAmount}();

        uint beforeBalance = c.balances(address(this));
        require(beforeBalance == depositAmount);
        uint beforeContractBal = address(c).balance;
        uint minSum = c.MinSum();

        bool reverted;
        if (beforeBalance >= minSum) {
            try c.Collect(beforeBalance) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        if (beforeBalance >= minSum) {
            assert(!reverted);
            uint afterBalance = c.balances(address(this));
            assert(afterBalance == 0 && address(c).balance == beforeContractBal - beforeBalance);
        } else {
            assert(reverted || (c.balances(address(this)) == beforeBalance && address(c).balance == beforeContractBal));
        }
    }

    receive() external payable {}
}

