contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    receive() external payable {}

    function run(uint _am) public {
        // Precondition: caller balance is below MinSum (possible because MinSum defaults to 1 ether
        // and the caller has not deposited anything, balance = 0 < 1 ether).
        // Ensure MinSum is at least 1 wei so the precondition can hold.
        // We cannot set MinSum to 0 because that would make the precondition false for all _am.
        // MinSum defaults to 1 ether, which is > 0, so we rely on that.

        // Ensure the caller has no balance in c (fresh contract, but be explicit by not depositing).
        // Read before-values.
        uint beforeCallerBal = c.balances(address(this));
        uint beforeContractBal = address(c).balance;
        uint minSum = c.MinSum();

        // The precondition must hold: caller balance < MinSum.
        require(beforeCallerBal < minSum, "precondition: balance must be below MinSum");

        bool reverted;
        try c.Collect(_am) { reverted = false; } catch { reverted = true; }

        uint afterCallerBal = c.balances(address(this));
        uint afterContractBal = address(c).balance;

        // The general rule: when the caller's balance is below MinSum, Collect is a no-op
        // (it does not revert, does not change the caller's balance, and does not move Ether).
        assert(!reverted
            && afterCallerBal == beforeCallerBal
            && afterContractBal == beforeContractBal);
    }
}

